import{_ as a,o as i,c as o,a2 as e}from"./chunks/framework.mRCPFc5l.js";const l="/assets/translation-provider.XRX2oW44.png",s="/assets/machine-translation.DgH5Tx5T.png",r="/assets/translation-review.DxF_Q48h.png",b=JSON.parse('{"title":"机器翻译","description":"","frontmatter":{},"headers":[],"relativePath":"06-machine-translation.md","filePath":"zh-CN/06-machine-translation.md"}'),n={name:"06-machine-translation.md"};function d(h,t,g,p,c,u){return i(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="机器翻译" tabindex="-1">机器翻译 <a class="header-anchor" href="#机器翻译" aria-label="Permalink to &quot;机器翻译&quot;">​</a></h1><p>生成翻译初稿，并在应用前审查模型结果。</p><h2 id="你可以在本页完成什么" tabindex="-1">你可以在本页完成什么 <a class="header-anchor" href="#你可以在本页完成什么" aria-label="Permalink to &quot;你可以在本页完成什么&quot;">​</a></h2><ul><li>配置 OpenAI-compatible 翻译服务和提示词。</li><li>选择集数范围并运行翻译。</li><li>取消任务、重试失败内容和查看日志。</li><li>审查模型结果，决定是否覆盖已有译文。</li><li>打开机器翻译结果备份。</li></ul><h2 id="配置翻译服务" tabindex="-1">配置翻译服务 <a class="header-anchor" href="#配置翻译服务" aria-label="Permalink to &quot;配置翻译服务&quot;">​</a></h2><p>机器翻译只在项目模式中使用，并要求项目已经导入字幕。</p><ol><li>打开 <strong>设置 → 机器翻译服务</strong>，或在机器翻译面板点击 <strong>管理服务</strong>。</li><li>点击 <strong>新建预设</strong>。</li><li>填写服务名称、Base URL、API Key 和模型。</li><li>根据服务能力决定是否启用流式响应和提示词缓存。</li><li>如有需要填写代理。</li><li>点击 <strong>保存预设</strong>。</li></ol><p>服务和提示词预设没有修改时，保存按钮不可点击；修改后还原或保存完成后也会恢复禁用状态。</p><p><img src="'+l+'" alt="机器翻译服务管理器，包含连接、能力和网络设置"></p><p>Base URL 需要包含服务的 <code>/v1</code> 路径。代理支持 HTTP、HTTPS、SOCKS5 和 SOCKS5H。API Key 和带认证信息的代理地址不应出现在截图、任务记录或共享日志中。</p><p>离开未保存的服务预设时，应用会要求保存、放弃或取消。多个窗口同时修改共享翻译设置时，会要求重新加载或明确覆盖。</p><h2 id="自定义请求参数和请求头" tabindex="-1">自定义请求参数和请求头 <a class="header-anchor" href="#自定义请求参数和请求头" aria-label="Permalink to &quot;自定义请求参数和请求头&quot;">​</a></h2><p>服务预设的“请求扩展”卡片位于“能力”和“网络”之间，包含“额外参数（YAML格式，可选）”和“额外请求头（YAML格式，可选）”两个多行输入框。卡片内部底部集中显示说明。</p><p>文本框中的灰色占位内容仅为示例，不会保存或发送。请按提供商文档和实际需求填写；无需扩展时留空。<strong>填写错误或使用提供商不支持的参数，可能导致翻译功能异常。</strong></p><h3 id="额外参数与推理优先级" tabindex="-1">额外参数与推理优先级 <a class="header-anchor" href="#额外参数与推理优先级" aria-label="Permalink to &quot;额外参数与推理优先级&quot;">​</a></h3><p>额外参数直接加入请求体，支持嵌套对象。例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">reasoning_effort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">high</span></span></code></pre></div><p>机器翻译面板的“推理”选择决定最终发送的 <code>reasoning_effort</code>：</p><table tabindex="0"><thead><tr><th>面板中的“推理”</th><th>YAML 配置</th><th>实际发送</th></tr></thead><tbody><tr><td>默认（Default）</td><td><code>reasoning_effort: high</code></td><td><code>reasoning_effort: high</code></td></tr><tr><td>低（Low）</td><td><code>reasoning_effort: high</code></td><td><code>reasoning_effort: low</code></td></tr><tr><td>无（None）</td><td><code>reasoning_effort: high</code></td><td><code>reasoning_effort: none</code></td></tr><tr><td>默认（Default）</td><td>未填写 <code>reasoning_effort</code></td><td>不发送此参数，使用提供商默认行为</td></tr></tbody></table><p>只有 <code>reasoning_effort</code> 遵循这条优先级规则。YAML 中的 <code>thinking</code>、<code>reasoning</code> 等其他参数不会随面板选择改变，具体支持情况请查阅提供商文档。“强制跳过推理”仍独立控制 assistant 预填消息，不受请求扩展影响。</p><h3 id="额外请求头、保存与保护" tabindex="-1">额外请求头、保存与保护 <a class="header-anchor" href="#额外请求头、保存与保护" aria-label="Permalink to &quot;额外请求头、保存与保护&quot;">​</a></h3><p>请求头名称和值必须为字符串，例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">X-Custom-Feature</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;enabled&quot;</span></span></code></pre></div><p>点击“保存预设”后，两项 YAML 会与其他全局翻译设置一起保存，重新打开并选择该预设即可读取；导入导出保留原文、注释和换行。自定义请求头以明文保存和导出。多窗口修改仍使用现有冲突处理。</p><p>模型、消息、温度、流式控制、认证及 HTTP 传输控制等受保护字段不能在这里覆盖。非法配置会阻止保存或运行；即使通过应用校验，提供商仍可能拒绝不支持的参数或组合。</p><p>只接受单文档 YAML 对象，不支持标签、锚点或别名；每项最多 64 KiB、20 层嵌套。</p><h2 id="管理翻译提示词" tabindex="-1">管理翻译提示词 <a class="header-anchor" href="#管理翻译提示词" aria-label="Permalink to &quot;管理翻译提示词&quot;">​</a></h2><ol><li>打开 <strong>设置 → 机器翻译提示词</strong>，或点击面板中的 <strong>管理提示词</strong>。</li><li>新建提示词预设。</li><li>输入名称和翻译指导。</li><li>保存预设。</li></ol><p>选择 <strong>不使用自定义提示词</strong> 后，项目会记住该选择，翻译请求只使用应用内置翻译规则，不会附加全局默认的自定义提示词。新项目尚未选择时，会使用全局默认的提示词预设（如有）。自定义内容适合项目风格、称谓、标点或特殊语气指导；术语对应关系更适合放在任务的 <strong>术语表</strong>。</p><h2 id="设置翻译范围" tabindex="-1">设置翻译范围 <a class="header-anchor" href="#设置翻译范围" aria-label="Permalink to &quot;设置翻译范围&quot;">​</a></h2><p><img src="'+s+'" alt="机器翻译面板，包含服务、提示词、任务选项、范围和日志"></p><p>在 <strong>分集</strong> 中可输入：</p><ul><li><code>all</code>：全部可用集。</li><li><code>1</code>：单集。</li><li><code>1 3</code> 或 <code>1,3</code>：多个集。</li><li><code>1-5,8</code>：范围与单集组合。</li></ul><p>无效集数或没有匹配集数时，<strong>运行翻译</strong>保持不可用。</p><h2 id="调整翻译选项" tabindex="-1">调整翻译选项 <a class="header-anchor" href="#调整翻译选项" aria-label="Permalink to &quot;调整翻译选项&quot;">​</a></h2><ul><li><strong>目标语言</strong>：任务的目标语言。</li><li><strong>服务</strong>：本次运行使用的服务预设。</li><li><strong>提示词</strong>：自定义翻译指导。</li><li><strong>温度</strong>：控制输出随机性；是否生效取决于模型。</li><li><strong>推理</strong>：选择“默认”时使用预设 YAML 的 <code>reasoning_effort</code>；选择非默认推理选项时使用面板所选值。两处都未指定时由提供商决定。</li><li><strong>并发数</strong>：同时保持的最大活动请求数。</li><li><strong>强制跳过推理（实验性）</strong>：默认不勾选。开启会强制添加 assistant 角色的预填消息（prefill），尝试跳过推理；不支持的模型可能产生意外结果，一般不建议开启。悬停可查看说明，已有项目保存的选择保持不变。</li><li><strong>术语表</strong>：按本次项目提供名称、术语和固定译法。</li></ul><p>面板中显示的值就是点击运行时使用的任务设置。项目会保存最近使用的选择。</p><h2 id="运行和取消翻译" tabindex="-1">运行和取消翻译 <a class="header-anchor" href="#运行和取消翻译" aria-label="Permalink to &quot;运行和取消翻译&quot;">​</a></h2><ol><li>确认服务、范围和选项。</li><li>点击 <strong>运行翻译</strong>。</li><li>在右侧 <strong>任务日志</strong> 查看进度和警告。</li></ol><p>并发槽位空闲后会立即领取下一项任务。超过 60 行的长集会自动拆成多个较小部分，结果仍按原集数和原始顺序合并。</p><p>运行中点击 <strong>取消</strong> 会停止派发并中止活动请求。随后选择：</p><ul><li><strong>保留已完成结果</strong>：继续处理已经完成且通过校验的结果。</li><li>丢弃：本次运行不修改工作区。</li></ul><h2 id="处理翻译失败" tabindex="-1">处理翻译失败 <a class="header-anchor" href="#处理翻译失败" aria-label="Permalink to &quot;处理翻译失败&quot;">​</a></h2><p>如果有失败集或失败分段，应用先暂存成功结果，并显示失败处理窗口：</p><ul><li><strong>重试失败分集</strong>：只重试失败项目；长集只重试失败分段。</li><li><strong>不重试并继续</strong>：保留成功结果，进入应用和冲突审查。</li></ul><p>在失败处理结束前，成功的空白译文不会提前写入工作区。认证、限流、网络、代理和格式校验错误会在日志中说明。</p><h2 id="审查并应用译文" tabindex="-1">审查并应用译文 <a class="header-anchor" href="#审查并应用译文" aria-label="Permalink to &quot;审查并应用译文&quot;">​</a></h2><p>通过校验且当前译文仍为空的行会自动应用。如果已有译文，则进入冲突审查。</p><p><img src="'+r+'" alt="翻译冲突审查显示原文、已有译文、新译文和选择列"></p><p>在审查窗口中：</p><ul><li>使用 <strong>全选</strong>、<strong>全不选</strong>、<strong>反选</strong> 或按集选择。</li><li>直接编辑 <strong>新译文</strong>；修改后该行会自动勾选。</li><li>点击行内非编辑框区域切换勾选。</li><li>点击 <strong>应用勾选替换</strong> 覆盖选中行。</li><li>点击 <strong>保留现有译文</strong> 放弃全部候选覆盖。</li></ul><p>未勾选候选等同于保留现有译文。把新译文编辑为空并应用，可明确清除已有译文。一次自动应用或一次批量冲突应用各形成一个撤销快照。</p><h2 id="查看翻译结果备份" tabindex="-1">查看翻译结果备份 <a class="header-anchor" href="#查看翻译结果备份" aria-label="Permalink to &quot;查看翻译结果备份&quot;">​</a></h2><p>点击 <strong>打开备份文件夹</strong>。每次进入结果应用阶段都会生成 CSV 备份，包含集数、时间、原文和模型返回且通过校验的译文。</p><p>备份保存的是模型原始有效输出，不代表当前工作区：</p><ul><li>不记录候选是否应用。</li><li>不随人工编辑、撤销或重做变化。</li><li>不包含 API Key、提示词、代理或任务设置。</li><li>格式错误或时间戳不匹配的输出不会写入备份。</li></ul><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><ul><li><strong>运行按钮不可用</strong>：先导入字幕、添加启用的服务，并修正集数范围。</li><li><strong>连接失败</strong>：检查 Base URL 是否包含 <code>/v1</code>、API Key、模型和代理地址。</li><li><strong>任务有警告但仍继续</strong>：服务明确不支持流式响应或提示词缓存时，应用可能自动回退；其他错误不会自动改为直连或换模型。</li><li><strong>结果没有自动覆盖旧译文</strong>：这是保护行为，已有译文必须人工审查并勾选。</li></ul>',58)])])}const m=a(n,[["render",d]]);export{b as __pageData,m as default};
